import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import { VlToasterComponent } from '@domg-wc/components/block';

// VlToasterComponent registreert ook vl-alert.
registerWebComponents([VlToasterComponent, VlButtonComponent]);

// De vl-alert in de toaster is niet zichtbaar: show() zonder argument toont een kloon van het eerste kind van de
// toaster.
document.querySelector('vl-button').addEventListener('vl-click', () => {
    const toaster = document.querySelector('vl-toaster');
    toaster.show();
});

components-block-toaster--toaster-show-a.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import { VlToasterComponent } from '@domg-wc/components/block';

registerWebComponents([VlToasterComponent, VlButtonComponent]);

document.querySelector('#button-technical-error').addEventListener('vl-click', () => {
    const toaster = document.querySelector('#toaster-show-alert');
    // showAlert() maakt een vl-alert en zet elke key met een waarde als attribuut.
    toaster.showAlert({
        title: 'Technische storing',
        icon: 'warning',
        type: 'warning',
        message: 'Door een technische storing is dit loket tijdelijk niet beschikbaar.',
        closable: true,
    });
});

components-block-toaster--toaster-fade-o.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import { VlLoaderComponent, VlToasterComponent } from '@domg-wc/components/block';

registerWebComponents([VlToasterComponent, VlButtonComponent, VlLoaderComponent]);

const toaster = document.querySelector('#toaster-fade-out');

// show(selector) toont een kloon, zonder id, van het kind van de toaster dat de selector aanwijst. Met fade-out
// verdwijnt de melding vanzelf: de animatie start na 4,4 s en duurt 0,3 s, daarna verwijdert de toaster ze.
document.querySelector('#button-error').addEventListener('vl-click', () => toaster.show('#alert-error'));
document.querySelector('#button-loader').addEventListener('vl-click', () => toaster.show('#alert-loader'));
